import re


def slugify(text):
    text = text.strip().lower()
    # Keep only ASCII letters, numbers, hyphens, and spaces
    text = re.sub(r"[^a-z0-9\s\-]+", "-", text)
    return text.strip("-").replace("-", "-")


def truncate(text, n):
    if len(text) <= n:
        return text
    return text[: n - 3] + "..."
EOF
